35	    34	  git('config', 'user.name', 'test');
36	    35	  writeFileSync(join(root, 'README.md'), '# WidgetWorks\n\nA fixture.\n');
37	    36	  git('add', '-A');
38	    37	  git('commit', '-qm', 'seed');
39	    38	  return root;
40	    39	}
