197	    29	  assert.equal(inside.severity, 'advisory');
198	    30	  assert.equal(inside.graceUntil, '2026-09-10');
199	    31	
200	    32	  const onTheDay = applyGrace([f], { now: at('2026-08-27T00:00:00Z') })[0];
201	    33	  assert.equal(onTheDay.severity, 'advisory', 'the day it was added is inside the window');
202	    34	
