289	     1	import { test } from 'node:test';
290	     2	import assert from 'node:assert/strict';
291	     3	import { execFileSync } from 'node:child_process';
292	     4	import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
293	     5	import { join, dirname } from 'node:path';
294	     6	import { tmpdir } from 'node:os';
