297	     9	
298	    10	const CANON = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
299	    11	const CHECK_THE_WORLD = join(CANON, 'engine/checks/check_the_world.mjs');
300	    12	
301	    13	// THE REGRESSION (#689). check_the_world is run BY A CONVERGE, from a process whose cwd
302	    14	// is inside `.claudinite/shared/` — the exact tree the converge has just deleted and
303	    15	// re-copied. On Linux that process keeps running in an unlinked directory, and so does
304	    16	// every child it spawns; `process.cwd()` in the child then throws `ENOENT … uv_cwd`
305	    17	// before a single check runs. The whole fleet reported `checks-could-not-run` on every
306	    18	// converging night because of it, which is indistinguishable from "this mount has no
307	    19	// checks" — so nothing surfaced it for as long as it was true.
308	    20	//
309	    21	// The test recreates that state literally rather than mocking it: a child chdirs into a
310	    22	// directory, deletes it, and only then spawns check_the_world. Without the
311	    23	// CLAUDE_PROJECT_DIR fallback this fails at the cwd call, exactly as the fleet did.
312	    24	
313	    25	// Spawn `check_the_world <args>` from a process whose cwd has been deleted, mimicking
314	    26	// the converge. Returns { status, stderr } instead of throwing so a failure is asserted
315	    27	// on rather than crashing the test.
316	    28	function fromDeletedCwd(args, env = {}) {
317	    29	  const box = mkdtempSync(join(tmpdir(), 'ctw-root-'));
318	    30	  const doomed = join(box, 'mount', 'packs', 'basics', 'tasks', 'baselining');
319	    31	  mkdirSync(doomed, { recursive: true });
320	    32	  // A minimal repo for the sweep to look at, OUTSIDE the directory that gets deleted.
321	    33	  const repo = join(box, 'repo');
322	    34	  mkdirSync(repo, { recursive: true });
323	    35	  writeFileSync(join(repo, '.claudinite-settings.json'), JSON.stringify({ packs: [] }, null, 2));
324	    36	
325	    37	  const driver = [
326	    38	    `process.chdir(${JSON.stringify(doomed)});`,
327	    39	    `require('node:fs').rmSync(${JSON.stringify(join(box, 'mount'))}, { recursive: true, force: true });`,
328	    40	    'const { execFileSync } = require("node:child_process");',
329	    41	    `try { execFileSync(process.execPath, ${JSON.stringify([CHECK_THE_WORLD, ...args])},`,
330	    42	    '  { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });',
331	    43	    '  console.log("STATUS 0");',
332	    44	    '} catch (e) { console.log("STATUS " + (e.status ?? "crash")); console.log(String(e.stderr ?? e.message)); }',
333	    45	  ].join('\n');
334	    46	
335	    47	  const out = execFileSync(process.execPath, ['-e', driver], {
336	    48	    encoding: 'utf8', env: { ...process.env, ...env }, cwd: box,
337	    49	  });
338	    50	  removeTree(box);
339	    51	  const [statusLine, ...rest] = out.split('\n');
340	    52	  return { status: statusLine.replace('STATUS ', '').trim(), stderr: rest.join('\n') };
341	    53	}
