344	    56	  const box = mkdtempSync(join(tmpdir(), 'ctw-repo-'));
345	    57	  writeFileSync(join(box, '.claudinite-settings.json'), JSON.stringify({ packs: [] }, null, 2));
346	    58	  const { status, stderr } = fromDeletedCwd(['--list'], { CLAUDE_PROJECT_DIR: box });
347	    59	  removeTree(box);
348	    60	  assert.doesNotMatch(stderr, /uv_cwd/, 'the cwd call must not be reached at all');
349	    61	  assert.equal(status, '0', `--list should succeed; stderr was:\n${stderr}`);
