363	     1	// The drift guard on CI's test roots.
364	     2	//
365	     3	// `.github/workflows/ci.yml` runs the suite from a CLOSED set of folders. That is the
366	     4	// right shape — it is short, it is readable, and it does not enumerate directory depth
367	     5	// — but a closed set has one failure mode: a test written somewhere outside it is never
368	     6	// run, and CI stays green while covering less. That is not hypothetical. The previous
369	     7	// form listed one glob per level of nesting, and `vendoring/` appeared in none of them,
370	     8	// so both of its test files went unrun for as long as they existed — a silent 38-test
371	     9	// hole nothing reported.
372	    10	//
373	    11	// So the root list is declared in ONE place (ci.yml, where CI actually reads it) and
374	    12	// this test holds it honest: every tracked `*.test.mjs` must fall under a declared root,
375	    13	// and every declared root must exist. Neither half is optional — the first catches a
376	    14	// test that escapes the set, the second catches a root left behind after a rename.
377	    15	//
378	    16	// It lives in engine-tests/ alongside the canon's other top-level-folder tests
379	    17	// (migrations.test.mjs): the roots span the whole repo, so no
380	    18	// pack owns them.
381	    19	
382	    20	import test from 'node:test';
383	    21	import assert from 'node:assert/strict';
384	    22	import { execFileSync } from 'node:child_process';
385	    23	import { existsSync, readFileSync } from 'node:fs';
386	    24	import { join } from 'node:path';
387	    25	import { fileURLToPath } from 'node:url';
388	    26	
389	    27	const REPO = fileURLToPath(new URL('..', import.meta.url));
390	    28	const CI = join(REPO, '.github/workflows/ci.yml');
391	    29	
392	    30	// The one line CI runs. Parsed rather than duplicated: a second copy of the root list
393	    31	// here would be the very drift this test exists to prevent.
394	    32	function declaredRoots() {
395	    33	  const line = readFileSync(CI, 'utf8').split('\n').find((l) => l.trim().startsWith('tests=('));
396	    34	  assert.ok(line, 'ci.yml no longer has a `tests=(...)` array — this guard has lost its subject');
397	    35	  const inner = line.slice(line.indexOf('(') + 1, line.lastIndexOf(')'));
398	    36	  return inner.split(/\s+/).filter(Boolean).map((g) => {
399	    37	    const at = g.indexOf('/**/');
400	    38	    assert.notEqual(at, -1, `test glob ${g} is not a \`<root>/**/…\` sweep — depth must not be enumerated`);
401	    39	    return g.slice(0, at);
402	    40	  });
403	    41	}
