8	// packs/directory.GENERATED.md is the full catalog of adoptable packs, vendored
9	// into every consumer's mount regardless of declaration (compute-vendor-set
10	// includes it unconditionally) so a member session can see what it could add,
11	// not just what it already runs. The manifests are the single source of truth;
12	// this test renders the catalog from them and maintains the committed artifact:
13	// locally it regenerates the file into the working tree (deterministic — no
14	// timestamps, so an up-to-date run yields no diff), under CI it only asserts,
15	// so a pack change that forgets to regenerate fails there with the fix named.
16	const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
17	
18	// Escape a manifest string for a table cell: it must stay on the row's one line
19	// and must not open a new column.
20	const cell = (s) => String(s).replace(/\|/g, '\\|').replace(/\s+/g, ' ').trim();
21	
22	// How a pack comes to be active, from the same manifest fields bootstrap's
23	// --init reads: seeding, a fingerprint marker, or plain declaration. A pack can
24	// be both seeded and fingerprinted; a pack with neither is opt-in by hand.
25	function activation(pack) {
26	  const parts = [];
27	  if (pack.seededByDefault) parts.push('seeded by bootstrap `--init`');
28	  if (pack.marker) parts.push(`fingerprinted: ${cell(pack.marker)}`);
29	  return parts.length ? parts.join('; ') : 'declared by hand (opt-in)';
30	}
31	
32	// The catalog is what the corpus OFFERS, not everything it holds: a `hidden`
33	// pack (pack-schema.mjs) is left out of it entirely, so no session routes a
34	// lesson to it or suggests adopting it. It stays declarable by hand.
35	export function renderPackDirectory(packs) {
36	  const rows = [...packs]
37	    .filter((p) => !p.hidden)
38	    .sort((a, b) => a.id.localeCompare(b.id))
39	    .map((p) => `| \`${p.id}\` | ${cell(p.ruleRoutingGuidance?.belongs ?? '')} | ${cell(p.ruleRoutingGuidance?.excludes ?? '')} | ${activation(p)} | ${p.requires?.length ? p.requires.map((r) => `\`${r}\``).join(', ') : '—'} |`);
40	  return `# Claudinite packs — the full directory
41	
42	Every pack this repo can adopt from Claudinite, whether or not it is declared here yet. A pack
43	activates only when declared in \`.claudinite-settings.json\`; adding one is the \`adopt-pack\`
44	skill's job (declare, interview, re-vendor, scaffold). A fingerprint marker only *suspects* a
45	pack is wanted — declaring it is always the project's call.
46	
47	GENERATED — do not hand-edit. Rendered from the pack manifests by the canon's
48	\`engine-tests/pack-directory.test.mjs\`; regenerate by running that test in a canon checkout.
49	
50	| Pack | What it covers | Not this pack | Activation | Requires |
51	|---|---|---|---|---|
52	${rows.join('\n')}
53	`;
54	}
