56	test('packs/directory.GENERATED.md is current with the pack manifests', async () => {
57	  const packs = await loadPacks(); // canon packs only — the catalog a repo adopts FROM
58	  assert.ok(packs.length > 0, 'pack discovery found nothing — the catalog would be empty');
59	
60	  const rendered = renderPackDirectory(packs);
61	  for (const p of packs) {
62	    if (p.hidden) {
63	      assert.doesNotMatch(rendered, new RegExp(`^\\| \`${p.id}\` \\|`, 'm'), `hidden pack "${p.id}" is rendered into the catalog`);
64	      continue;
65	    }
66	    assert.match(rendered, new RegExp(`^\\| \`${p.id}\` \\|`, 'm'), `no row rendered for pack "${p.id}"`);
67	  }
68	
69	  const path = join(ROOT, PACK_DIRECTORY_FILE);
70	  if (!process.env.CI && (!existsSync(path) || readFileSync(path, 'utf8') !== rendered)) {
71	    writeFileSync(path, rendered);
72	  }
73	  assert.ok(existsSync(path), `${PACK_DIRECTORY_FILE} is missing — run this test locally (it regenerates the file) and commit the result`);
74	  assert.equal(
75	    readFileSync(path, 'utf8'), rendered,
76	    `${PACK_DIRECTORY_FILE} is stale against the pack manifests — run this test locally (it regenerates the file) and commit the result in the same change that touched the packs`
77	  );
78	});
79	
80	// A hidden pack is content the corpus carries but does not offer: it loads,
81	// runs and stays declarable by hand, and the catalog simply never names it.
82	// Asserted against a synthetic manifest as well as the real tree, so the rule
83	// keeps its teeth in a corpus where nothing happens to be hidden.
84	test('renderPackDirectory omits a hidden pack', () => {
85	  const pack = (id, extra) => ({ id, ruleRoutingGuidance: { belongs: `${id} belongs`, excludes: `${id} excludes` }, ...extra });
86	  const rendered = renderPackDirectory([pack('visible-pack'), pack('hidden-pack', { hidden: true })]);
87	  assert.match(rendered, /^\| `visible-pack` \|/m);
88	  assert.doesNotMatch(rendered, /hidden-pack/);
89	});
