1	// THE PAGE'S IMPORT GRAPH MUST STAY BROWSER-PURE.
2	//
3	// The dashboard is served as raw ESM: the browser fetches `index.html`, follows its
4	// module script, and follows every relative import from there — including the reaches
5	// into `../../engine/`, which is the whole point of the design (the page imports the
6	// mechanism it renders rather than restating it). Nothing bundles, so there is no build
7	// step to rewrite a `node:` builtin into something a browser can load. One such import
8	// anywhere in the graph fails the page's FIRST module load, and the whole dashboard is
9	// a blank screen.
10	//
11	// It fails in the browser and NOWHERE ELSE — every Node test keeps passing, since Node
12	// resolves `node:fs` happily — so the property is pinned here.
13	//
14	// The graph is WALKED rather than listed. A hand-kept list of "the engine modules the
15	// page imports" is a snapshot of one day's graph: it stayed green while the page grew
16	// an import of `engine/settings-file.mjs`, which reads the disk (#1286). Walking from
17	// the real entry point means a module the page starts importing tomorrow is covered the
18	// day it is imported.
19	import { test } from 'node:test';
20	import assert from 'node:assert/strict';
21	import { readFile } from 'node:fs/promises';
22	import { fileURLToPath } from 'node:url';
23	import { dirname, resolve, relative } from 'node:path';
24	
25	const HERE = dirname(fileURLToPath(import.meta.url));
26	const PAGE = resolve(HERE, '..');
27	const ROOT = resolve(PAGE, '../..');
28	
29	// Import statements only. A `from '…'` inside a string literal is prose the page
30	// renders, not an edge of the graph, so the statement's own keyword has to be there.
31	const IMPORTS = /(?:^|[\n;])\s*(?:import|export)\b[^;]*?from\s*'([^']+)'/g;
32	
33	const stripLineComments = (src) => src.replace(/^\s*\/\/.*$/gm, '');
34	
35	// Every file the browser would load, starting from whatever `index.html` actually
36	// names — so a renamed entry point re-points the walk instead of silently emptying it.
37	async function graph() {
38	  const html = await readFile(resolve(PAGE, 'index.html'), 'utf8');
39	  const entry = html.match(/<script[^>]*\btype="module"[^>]*\bsrc="([^"]+)"/)?.[1];
40	  assert.ok(entry, 'index.html names no module entry point — the walk would cover nothing');
41	
42	  const files = new Map();
43	  const visit = async (file) => {
44	    if (files.has(file)) return;
45	    const code = stripLineComments(await readFile(file, 'utf8'));
46	    files.set(file, code);
47	    for (const [, spec] of code.matchAll(IMPORTS)) {
48	      if (!spec.startsWith('.')) continue;                 // judged by the caller, not followed
49	      await visit(resolve(dirname(file), spec));
50	    }
51	  };
52	  await visit(resolve(PAGE, entry));
53	  return files;
54	}
55	
56	test('every module the page loads is browser-pure', async () => {
57	  const files = await graph();
58	  assert.ok(files.size > 20, `the walk reached only ${files.size} files — it is not covering the page`);
59	
60	  for (const [file, code] of files) {
61	    const rel = relative(ROOT, file);
62	    for (const [, spec] of code.matchAll(IMPORTS)) {
63	      assert.ok(
64	        spec.startsWith('.'),
65	        `${rel} imports '${spec}' — the page loads unbundled, so only relative specifiers resolve`,
66	      );
67	    }
68	    assert.doesNotMatch(code, /\brequire\s*\(/, `${rel} uses require()`);
69	    assert.doesNotMatch(code, /\bprocess\./, `${rel} touches process`);
70	  }
71	});
72	
73	// The reach into the engine is the design, so the walk has to prove it happened: a page
74	// that stopped importing the engine would satisfy every assertion above trivially.
75	test('the walk reaches the engine modules the page renders', async () => {
76	  const files = [...(await graph()).keys()].map((f) => relative(ROOT, f));
77	  assert.ok(
78	    files.some((f) => f.startsWith('packs/claudinite-tasks/queue/')),
79	    'the page no longer imports the queue modules it renders',
80	  );
81	});
