467	    40	// has ever carried, as `{ enginePath -> Set<symbol> }`.
468	    41	function fieldedEngineImports() {
469	    42	  // One log walk over the pack tree, with each commit's blobs; `-p` gives the diffs
470	    43	  // and the added lines are what a member could have installed.
471	    44	  const text = git('log', TRUNK, '--format=%H', '-p', '--unified=0', '--', 'packs/');
472	    45	  const out = new Map();
473	    46	  const RE = /^\+\s*import\s*\{([^}]*)\}\s*from\s*'[^']*?engine\/([^']+)'/;
474	    47	  // A pack's tests live inside the pack and are dropped from every vendor set, so no
475	    48	  // member ever holds one — their imports are not fielded, and counting them would
476	    49	  // pin an engine symbol alive on the strength of a file nobody installs. The `+++`
477	    50	  // header names the file each run of added lines belongs to.
478	    51	  let file = '';
479	    52	  for (const line of text.split('\n')) {
480	    53	    if (line.startsWith('+++ ')) { file = line.slice(4).replace(/^b\//, ''); continue; }
481	    54	    if (file.endsWith('.test.mjs')) continue;
482	    55	    const m = RE.exec(line);
483	    56	    if (!m) continue;
484	    57	    const path = `engine/${m[2].replace(/^(\.\.\/)+/, '')}`;
485	    58	    const syms = m[1].split(',').map((s) => s.trim().split(/\s+as\s+/)[0].trim()).filter(Boolean);
486	    59	    if (!out.has(path)) out.set(path, new Set());
487	    60	    for (const s of syms) out.get(path).add(s);
488	    61	  }
489	    62	  return out;
490	    63	}
