15	// The install runner exits non-zero when the converged tree fails its self-test, which
16	// a bare temp directory always does — no git, no mount. These tests assert on what it
17	// REPORTS, so the exit code is not the subject and stdout is read either way.
18	const runReporting = async (...args) => {
19	  try { return await run(...args); } catch (e) { return { stdout: e.stdout ?? '', stderr: e.stderr ?? '' }; }
20	};
21	const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
22	const PACK_DIR = join(ROOT, 'packs/claudinite-dashboard');
