24	// --- the manifest ----------------------------------------------------------------
25	
26	test('the pack is opt-in and never fingerprinted', () => {
27	  // Nothing in a repo's shape implies wanting a dashboard. A fingerprint would suspect
28	  // one in every member on the fleet, since every member has a scheduler. Silence IS
29	  // that statement: the manifest declares neither field, and the loader resolves an
30	  // undeclared fingerprint to null.
31	  assert.equal(pack.detect, undefined);
32	  assert.equal(pack.marker, undefined);
33	  assert.equal(pack.seededByDefault, false);
34	});
