36	test('it costs no session prose, and its one check guards the descriptors', () => {
37	  // A page is not a practice: there is no way to write the dashboard wrongly in a
38	  // consuming repo, and prose here would bill every session in every declaring repo.
39	  // No RULES.md beside the manifest is what says so — the loader derives prose from
40	  // that file's presence, so its absence is the declaration.
41	  assert.equal(existsSync(join(PACK_DIR, 'RULES.md')), false);
42	  assert.equal(pack.prose, undefined);
43	  // The one check guards what OTHER packs contribute to this page — a descriptor the
44	  // reader rejects fails silently, in a viewer's browser, where its author never
45	  // looks. It is a world rule: it audits what has landed, whatever this session
46	  // touched.
47	  // It is the module in the pack's own worldRules/ — the directory is the
48	  // declaration, so the directory is what this asserts.
49	  assert.deepEqual(readdirSync(join(PACK_DIR, 'worldRules')).sort(),
50	    ['descriptor-usable.mjs']);
51	  assert.equal(existsSync(join(PACK_DIR, 'workRules')), false);
