54	// The whole point of the remodel: adoption is what wires the deploy, because
55	// `.github/workflows/` cannot be written by the nightly and so can only be seeded.
56	test('adoption seeds the Pages workflow, and its template exists', async () => {
57	  assert.equal(pack.seedOps.length, 1);
58	  const [op] = pack.seedOps;
59	  assert.equal(op.dest, '.github/workflows/claudinite-dashboard-pages.yml');
