63	// A seeded workflow never converges, so anything it hardcodes is frozen in every
64	// member forever. It therefore holds only what needs a workflow job — the Pages
65	// actions, which `uses:` alone can invoke — and no logic: the build, its inputs and
66	// the decision to run are the publish-pages task's.
67	test('the seeded workflow is the Pages actions and nothing else', async () => {
68	  const yml = await readFile(join(PACK_DIR, pack.seedOps[0].template), 'utf8');
69	  const steps = [...yml.matchAll(/^\s+(?:- )?uses: ([^@\n]+)@/gm)].map((m) => m[1]);
70	  assert.deepEqual(steps, ['actions/checkout', 'actions/configure-pages', 'actions/upload-pages-artifact', 'actions/deploy-pages']);
71	  assert.doesNotMatch(yml, /^\s+run:/m, 'a run: step is logic the frozen file cannot converge');
72	  assert.match(yml, /ref: gh-pages/, 'it deploys the tree the task pushed');
73	  // Configuration reaches the build task-side, so the frozen file has none to go stale.
74	  assert.doesNotMatch(yml, /vars\./, 'settings belong in the declaration and the variables, read by the task');
