94	// Stand up a member the way a converge leaves one: the pack and the engine side by
95	// side under `.claudinite/shared/`. The relative imports the page uses resolve only
96	// if that shape is right, so building here is what proves the shape.
97	async function member(declaration, extraFiles = {}) {
98	  const dir = await mkdtemp(join(tmpdir(), 'cd-member-'));
99	  await mkdir(join(dir, '.claudinite/shared/packs'), { recursive: true });
100	  await cp(join(ROOT, 'engine'), join(dir, '.claudinite/shared/engine'), { recursive: true });
101	  // The queue modules the page reads through the tasks pack's published shared-code/.
102	  await cp(join(ROOT, 'packs/claudinite-tasks'), join(dir, '.claudinite/shared/packs/claudinite-tasks'), { recursive: true });
103	  // As the vendor set lays it down: a pack's tests sit beside the files they cover and
104	  // are dropped on the way into a mount, so a fixture that copied them would be staging
105	  // a tree no member ever has.
106	  await cp(PACK_DIR, join(dir, '.claudinite/shared/packs/claudinite-dashboard'),
107	    { recursive: true, filter: (src) => !src.endsWith('.test.mjs') });
108	  await writeFile(join(dir, '.claudinite-settings.json'), JSON.stringify(declaration));
109	  for (const [name, body] of Object.entries(extraFiles)) await writeFile(join(dir, name), body);
110	  return dir;
111	}
