26	  cpSync(join(REPO_ROOT, 'engine', 'pack_loader'), join(root, 'engine', 'pack_loader'), { recursive: true });
27	  // pack-schema validates a version against the engine's version module, which sits
28	  // beside pack_loader in the real tree.
29	  cpSync(join(REPO_ROOT, 'engine', 'version.mjs'), join(root, 'engine', 'version.mjs'));
30	  // Where a member's settings live: the loader resolves the declaration through it.
31	  for (const f of ['settings-file.mjs', 'settings-file-names.mjs']) cpSync(join(REPO_ROOT, 'engine', f), join(root, 'engine', f));
32	  for (const [id, def] of Object.entries(packs)) {
33	    const { skills = [], ...manifest } = def;
