14	  find(cls) {
15	    const hit = [];
16	    if (this.className.split(' ').includes(cls)) hit.push(this);
17	    for (const c of this.children) if (c instanceof FakeEl) hit.push(...c.find(cls));
18	    return hit;
19	  }
20	}
