66	// A scripted gh double: replays labeledIssues' underlying paged read, records writes.
67	function ghDouble({ open = [], closed = [] } = {}) {
68	  const writes = [];
69	  const gh = async (path, init) => {
70	    if (init) { writes.push({ path, ...init }); return { status: path.endsWith('/issues') || path.endsWith('/labels') ? 201 : 200, json: { number: 90 } }; }
71	    if (path.includes('/issues?')) {
72	      // labeledIssues pages state=all; one page is enough for a test double.
73	      const items = [...open.map((i) => ({ ...i, state: 'open' })), ...closed.map((i) => ({ ...i, state: 'closed' }))];
74	      return { status: 200, json: items };
75	    }
76	    return { status: 200, json: {} };
77	  };
78	  gh.writes = writes;
79	  return gh;
80	}
