888	   295	  const gh = async (path, { method = 'GET', body } = {}) => {
889	   296	    let m;
890	   297	    if (method === 'GET' && /\/issues\?/.test(path)) {
891	   298	      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1);
892	   299	      return { status: 200, json: page === 1 ? state.issues.filter((i) => i.state === 'open') : [] };
893	   300	    }
894	   301	    if ((m = /\/issues\/comments\/(\d+)$/.exec(path))) {
895	   302	      for (const i of state.issues) {
896	   303	        const c = i.comments.find((x) => x.id === Number(m[1]));
897	   304	        if (c) { if (method === 'PATCH') c.body = body.body; return { status: 200, json: c }; }
898	   305	      }
899	   306	      return { status: 404, json: null };
900	   307	    }
901	   308	    if ((m = /\/issues\/(\d+)\/comments/.exec(path))) {
902	   309	      const issue = find(Number(m[1]));
903	   310	      if (method === 'POST') { issue.comments.push({ id: (state.commentSeq += 1), body: body.body }); return { status: 201, json: {} }; }
904	   311	      return { status: 200, json: issue.comments };
905	   312	    }
906	   313	    if ((m = /\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
