910	   317	    }
911	   318	    if ((m = /\/issues\/(\d+)\/labels$/.exec(path))) {
912	   319	      find(Number(m[1])).labels.push(...body.labels);
913	   320	      return { status: 200, json: {} };
914	   321	    }
915	   322	    if ((m = /\/issues\/(\d+)$/.exec(path))) {
