107	// metadata (the fixtures above) skips the guards, which the earlier tests
108	// already exercise by passing an arbitrary --ref.
109	function gitify(canon) {
110	  const g = (...args) => execFileSync('git', args, { cwd: canon, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim();
111	  g('init', '-q');
112	  g('config', 'user.email', 'test@test');
113	  g('config', 'user.name', 'test');
114	  g('add', '-A');
115	  g('commit', '-q', '-m', 'c1');
116	  const c1 = g('rev-parse', 'HEAD');
117	  writeFileSync(join(canon, 'engine', 'checks', 'check_the_world.mjs'), 'engine v3\n');
118	  g('add', '-A');
119	  g('commit', '-q', '-m', 'c2');
120	  const c2 = g('rev-parse', 'HEAD');
121	  return [c1, c2];
122	}
