import sys
def rep(path, pairs):
    src = open(path, encoding='utf8').read()
    for old, new in pairs:
        n = src.count(old)
        if n != 1: sys.exit(f'{path}: found {n} of {old[:70]!r}')
        src = src.replace(old, new)
    open(path, 'w', encoding='utf8').write(src); print('ok', path)

